import{_ as e,o as a,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ97 记负均正","description":"描述 首先输入要输入的整数个数n，然后输入n个整数。输出为n个整数中负数的个数，和所有正整数的平均值，结果保留一位小数。 0即不是正整数，也不是负数，不计入计算。如果没有正数，则平均值为0。 数据范围： 1≤ n ≤2000 ，输入的整数都满足 ∣ val ∣≤1000 输入描述。","frontmatter":{"title":"HJ97 记负均正","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 首先输入要输入的整数个数n，然后输入n个整数。输出为n个整数中负数的个数，和所有正整数的平均值，结果保留一位小数。 0即不是正整数，也不是负数，不计入计算。如果没有正数，则平均值为0。 数据范围： 1≤ n ≤2000 ，输入的整数都满足 ∣ val ∣≤1000 输入描述。","sidebarWeight":47,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为入门题/HJ97 记负均正.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ97 记负均正.md","filePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ97 记负均正.md"}'),i={name:"posts/前端面试与实战/03-算法训练/华为入门题/HJ97 记负均正.md"};function r(s,t,l,p,c,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<div><h1 id="hj97-记负均正" tabindex="-1">HJ97 记负均正 <a class="header-anchor" href="#hj97-记负均正" aria-label="Permalink to &quot;HJ97 记负均正&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ97 记负均正”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 首先输入要输入的整数个数n，然后输入n个整数。输出为n个整数中负数的个数，和所有正整数的平均值，结果保留一位小数。 0即不是正整数，也不是负数，不计入计算。如果没有正数，则平均值为0。 数据范围： 1≤<em>n</em> ≤2000 ，输入的整数都满足 ∣<em>val</em>∣≤1000 <strong>输入描述：</strong> 首先输入一个正整数n， 然后输入n个整数。 <strong>输出描述：</strong> 输出负数的个数，和所有正整数的平均值。 <strong>示例1</strong> 输入： 11 1 2 3 4 5 6 7 8 9 0 -1 ==复制== 输出： 1 5.0 ==复制== <strong>示例2</strong> 输入： 30 0 0 ==复制== 输出： 0 0.0 ==复制==</p></blockquote><p>while True: try:</p><h1 id="读取数字个数-本行未使用-可优化掉" tabindex="-1">读取数字个数（本行未使用，可优化掉） <a class="header-anchor" href="#读取数字个数-本行未使用-可优化掉" aria-label="Permalink to &quot;读取数字个数（本行未使用，可优化掉）&quot;">​</a></h1><p>count = int(input().strip())</p><h1 id="读取一行数字-并转换为整数列表" tabindex="-1">读取一行数字，并转换为整数列表 <a class="header-anchor" href="#读取一行数字-并转换为整数列表" aria-label="Permalink to &quot;读取一行数字，并转换为整数列表&quot;">​</a></h1><p>num_list = map(int, input().strip().split())</p><h1 id="初始化负数数量和非负数-正数-总和及数量" tabindex="-1">初始化负数数量和非负数（正数）总和及数量 <a class="header-anchor" href="#初始化负数数量和非负数-正数-总和及数量" aria-label="Permalink to &quot;初始化负数数量和非负数（正数）总和及数量&quot;">​</a></h1><p>negative_count = 0 positive_sum = 0 positive_count = 0 # 遍历数字列表 for n in num_list: if n &lt; 0:</p><h1 id="如果是负数-负数计数器增加" tabindex="-1">如果是负数，负数计数器增加 <a class="header-anchor" href="#如果是负数-负数计数器增加" aria-label="Permalink to &quot;如果是负数，负数计数器增加&quot;">​</a></h1><p>negative_count += 1 elif n &gt; 0:</p><h1 id="如果是正数-累加到正数总和中-并增加正数计数器" tabindex="-1">如果是正数，累加到正数总和中，并增加正数计数器 <a class="header-anchor" href="#如果是正数-累加到正数总和中-并增加正数计数器" aria-label="Permalink to &quot;如果是正数，累加到正数总和中，并增加正数计数器&quot;">​</a></h1><p>positive_sum += n positive_count += 1 # 如果有正数，计算平均值，否则平均值为0.0 avg = positive_sum / positive_count if positive_count &gt; 0 else 0.0 # 输出负数数量和非负数平均值（保留一位小数） print(f&quot;{negative_count} {avg:.1f}&quot;) except EOFError:</p><h1 id="当读取到文件末尾时退出循环" tabindex="-1">当读取到文件末尾时退出循环 <a class="header-anchor" href="#当读取到文件末尾时退出循环" aria-label="Permalink to &quot;当读取到文件末尾时退出循环&quot;">​</a></h1><p>break</p></div>',1)])])}const _=e(i,[["render",r]]);export{u as __pageData,_ as default};
